messages.content:
{
  "summary": "I located your account and the affected line. Because you’re in France, I enabled international data roaming on your line so your phone can use partner networks for mobile data.",
  "what_i_did": {
    "account_found_for": "555-123-2002",
    "line_status": "Active",
    "plan": {
      "name": "Premium Plan",
      "monthly_data_limit_gb": 15,
      "refuel_price_per_gb_usd": 2
    },
    "current_cycle_usage": {
      "used_gb": 8.7,
      "limit_gb": 15,
      "cycle_ends": "2025-02-28"
    },
    "roaming": {
      "was_enabled_on_our_side": true,
      "reason": "You’re abroad and roaming was previously off on the line"
    }
  },
  "why_this_helps": "With roaming enabled on your line, your phone is allowed to use partner networks abroad. Now we need to ensure your phone’s own settings (data roaming, network mode, Data Saver, VPN, APN) are optimized for speed.",
  "next_steps_for_you": [
    {
      "step": 1,
      "action": "Ensure phone-side Data Roaming is ON",
      "how": "Use toggle_roaming() on your phone to turn Data Roaming ON.",
      "why": "Your line now allows roaming; your phone must also allow it to use data abroad."
    },
    {
      "step": 2,
      "action": "Confirm mobile data is ON",
      "how": "Run check_network_status(). If it shows mobile data OFF, use toggle_data() to turn it ON.",
      "why": "Data must be enabled to use the internet over cellular."
    },
    {
      "step": 3,
      "action": "Prefer fastest networks",
      "how": "Run check_network_mode_preference(). If it’s 2G/3G, set set_network_mode_preference(\"4g_5g_preferred\").",
      "why": "4G/5G provide the best speeds; older modes are slow."
    },
    {
      "step": 4,
      "action": "Turn OFF Data Saver",
      "how": "Run check_data_restriction_status(). If Data Saver is ON, use toggle_data_saver_mode() to turn it OFF.",
      "why": "Data Saver can make apps feel slow or unresponsive."
    },
    {
      "step": 5,
      "action": "Turn OFF any VPN (for testing)",
      "how": "Run check_vpn_status(). If connected, use disconnect_vpn().",
      "why": "Some VPNs significantly reduce speed, especially on roaming."
    },
    {
      "step": 6,
      "action": "Quick network refresh",
      "how": "Use toggle_airplane_mode() ON for 10 seconds, then OFF.",
      "why": "Forces a fresh attachment to the fastest available network."
    },
    {
      "step": 7,
      "action": "Test speed",
      "how": "With Wi‑Fi OFF, run run_speed_test().",
      "why": "Confirms current cellular performance; we aim for “excellent”."
    },
    {
      "step": 8,
      "action": "If data still stops/very slow: verify APN",
      "how": "Run check_apn_settings(). If APN/MMSC look incorrect, use reset_apn_settings() then reboot_device().",
      "why": "Incorrect APN can break or slow mobile data. Reboot applies changes."
    }
  ],
  "please_reply_with": {
    "required_checks": [
      "Results of check_network_status() (signal bars, network type like 5G/4G, and that Data Roaming and Mobile Data show ON)",
      "Result of check_network_mode_preference()",
      "Result of check_data_restriction_status()",
      "Result of check_vpn_status()",
      "Speed rating from run_speed_test() (unknown/very poor/poor/fair/good/excellent)"
    ],
    "extra_context": [
      "Rough location in France (city/area) and whether the issue happens everywhere or just in that area",
      "When the problem started"
    ]
  },
  "notes": [
    "You have used 8.7 GB of 15 GB this cycle, so you are not at your plan’s data limit.",
    "If speeds are still not excellent after these steps, I can continue with additional checks."
  ]
}

