{
  "summary": "Airplane Mode is ON, which shuts off all cellular radios. That’s why there’s no signal and mobile data is OFF. We’ll turn Airplane Mode OFF first, then enable mobile data and optimize settings for best speed.",
  "reassurance": "None of the steps below (turning off Airplane Mode, enabling data, changing network mode, or rebooting) will delete your photos or personal data.",
  "steps": [
    {
      "step": 1,
      "action": "Turn OFF Airplane Mode",
      "how": "Use toggle_airplane_mode() to switch Airplane Mode OFF. Wait ~10–15 seconds.",
      "what_to_expect": "Signal bars should reappear and a network type (4G/5G) should show."
    },
    {
      "step": 2,
      "action": "Confirm mobile data is ON",
      "how": "Run check_network_status(). If it shows mobile data disabled, use toggle_data() to turn it ON.",
      "why": "Data must be enabled to use the internet over cellular."
    },
    {
      "step": 3,
      "action": "Prefer fastest networks",
      "how": "Run check_network_mode_preference(). If it shows 2G/3G, set set_network_mode_preference(\"4g_5g_preferred\").",
      "why": "4G/5G provide the best speeds, especially while roaming."
    },
    {
      "step": 4,
      "action": "Turn OFF Data Saver and any VPN (for testing)",
      "how": "Run check_data_restriction_status() and check_vpn_status(). If Data Saver is ON, use toggle_data_saver_mode() to turn it OFF. If a VPN is connected, use disconnect_vpn().",
      "why": "Both can significantly slow data, particularly on roaming networks."
    },
    {
      "step": 5,
      "action": "Test the connection speed",
      "how": "With Wi‑Fi OFF, run run_speed_test().",
      "goal": "We’re aiming for “excellent.” If it’s lower, we’ll keep tuning."
    }
  ],
  "if_no_signal_after_step_1": [
    "Run check_sim_status(). If it shows Missing, use reseat_sim_card() and try again.",
    "If SIM is Active but still no signal, perform a quick restart with reboot_device(). Then repeat Steps 2–5."
  ],
  "why_these_steps": "Turning off Airplane Mode restores cellular radios. Enabling mobile data and preferring 4G/5G ensures the phone uses the fastest available roaming network in France. Disabling Data Saver/VPN removes common speed bottlenecks.",
  "please_reply_with": [
    "Updated check_network_status() after turning Airplane Mode OFF (signal bars and network type, confirm mobile data ON and roaming ON).",
    "Result of check_network_mode_preference().",
    "Result of check_data_restriction_status() and check_vpn_status().",
    "Speed rating from run_speed_test() (unknown/very poor/poor/fair/good/excellent).",
    "Your current city/area in France and whether speeds improve after these steps."
  ]
}

