  "message": "I can help you get your service back. First I’ll verify your line’s status on our side (to rule out things like a suspension or SIM provisioning issue). In parallel, we’ll run a couple of quick checks on your phone to eliminate common causes like Airplane Mode or a loose SIM.",
  "what_i_need_from_you": {
    "identify_customer": "Please provide ONE of the following so I can pull up your account:",
    "options": [
      "The phone number of the affected line (preferred)",
      "Your customer ID",
      "Your full name AND date of birth (YYYY-MM-DD)"
    ],
    "additional_questions": [
      "Are you currently traveling outside your usual area or abroad?",
      "Is this issue affecting just this one phone or multiple devices on your account?"
    ]
  },
  "quick_checks_you_can_try_now": [
    {
      "step": "Check for Airplane Mode",
      "how": "Look at the top of your screen for an airplane icon. If you see it, turn Airplane Mode off from Quick Settings/Control Center or Settings."
    },
    {
      "step": "Look at signal indicators",
      "how": "Note what you see at the top of the screen: does it say “No Service,” or are there 0–4 signal bars? Do you see 5G/4G/LTE icons?"
    },
    {
      "step": "Toggle mobile data",
      "how": "Turn mobile data/cellular data off, wait 10 seconds, then turn it back on."
    },
    {
      "step": "Reseat the SIM (if your phone has a physical SIM)",
      "how": "Power off the phone, remove the SIM tray, gently reinsert the SIM so it sits flat, then power back on."
    },
    {
      "step": "Simple reboot",
      "how": "Restart your phone to refresh network registration."
    }
  ],
  "please_reply_with": [
    "The identifier (phone number/customer ID/full name + DOB) so I can check your line status.",
    "Your answers to the two additional questions (traveling? one device or multiple?).",
    "What you observed from the quick checks (airplane icon, signal bars, network type, results after reboot/SIM reseat)."
  ]
}

