messages.content:
{
  "message": "Thanks for the details. Since you see “No Service” (and not Airplane Mode), we’ll do two things: 1) have you run a couple of quick steps that force the phone to re-register on the network and re-detect the SIM, and 2) I’ll check your line status on our side to rule out any suspension or provisioning issue.",
  "why_these_steps": [
    "Toggling mobile data and rebooting forces a fresh network registration.",
    "Reseating a physical SIM resolves many ‘No Service’ cases caused by poor SIM contact."
  ],
  "next_steps_for_you": [
    {
      "step": "Toggle mobile data",
      "how": "Turn Mobile/Cellular Data OFF, wait 10 seconds, then turn it ON again.",
      "what_to_observe": "See if bars or a network type (5G/4G/LTE) appear instead of “No Service.”"
    },
    {
      "step": "Reboot the phone",
      "how": "Restart the device normally.",
      "what_to_observe": "After it powers back up, check if service returns."
    },
    {
      "step": "If still no service: Reseat the SIM (skip if you use eSIM)",
      "how": "Power off, remove the SIM tray, ensure the SIM sits flat and aligned, reinsert, then power on.",
      "what_to_observe": "Check the status bar again for signal or network type."
    }
  ],
  "please_reply_with": [
    "Whether service returned after each step (after data toggle, after reboot, after SIM reseat).",
    "Whether your device uses a physical SIM or eSIM.",
    "Your phone make/model (e.g., iPhone 13, Samsung S22), and any on-screen messages like “SIM not provisioned,” “Emergency calls only,” or “SIM locked.”"
  ],
  "what_i_will_do_next": "As soon as you start Step 1, I’ll begin checking your line status on our side to rule out suspension or SIM provisioning issues for 555-123-2002. I’ll update you with what I find."
}

