  "thought_process": "I can’t send MMS from your device remotely. Since your data connection is now healthy (44 Mbps on 4G with Data Roaming ON), your send test will confirm whether MMS is fixed. If it still fails, we’ll isolate whether it’s an MMS capability/app setting issue or a carrier-side provisioning block. I also still need your account details to verify/enable MMS/data roaming on the line.",
  "please_run_this_now": {
    "instructions": [
      "Keep Wi‑Fi OFF, Mobile Data ON, and Data Roaming ON.",
      "Send a very small photo (<300 KB) to yourself in the default Messages app.",
      "Send the same to a different contact."
    ],
    "report_back": [
      "MMS to yourself: yes/no",
      "MMS to other contact: yes/no",
      "App behavior: stuck on sending / fails immediately / retries / other details"
    ]
  },
  "if_mms_still_fails_next_steps": [
    {
      "step": "Check MMS capability",
      "do_this": "Run can_send_mms and share the result (true/false and any details)."
    },
    {
      "step": "Check Messages app background data setting",
      "do_this": "Run check_app_status with app_name=\"messaging\" and tell me if background data is restricted.",
      "if_restricted": "On Android: Settings > Apps > Messages > Mobile data & Wi‑Fi (or Data usage) > enable Background data and allow Unrestricted data usage. Then retry MMS."
    },
    {
      "step": "Airplane mode refresh (not yet tried)",
      "do_this": "Run toggle_airplane_mode ON, wait 10 seconds, then OFF. After reconnect, keep Wi‑Fi OFF and retry MMS."
    },
    {
      "step": "Lock temporarily to 4G",
      "do_this": "Run set_network_mode_preference with mode=\"4g_only\", retry MMS. If no change, switch back to \"4g_5g_preferred\" afterward."
    },
    {
      "step": "SIM refresh",
      "do_this": "Run check_sim_status (share result). If Active, run reseat_sim_card. After signal returns, retry MMS."
    }
  ],
  "account_verification_needed": {
    "why": "If MMS still fails with good data, it often indicates MMS/data roaming isn’t fully provisioned on the account. I can verify and enable it at no cost once I locate your account.",
    "please_provide_one_of": [
      "Customer ID (from your bill/account profile).",
      "If this is a family/business account: account holder’s full name and date of birth (YYYY-MM-DD).",
      "Another phone number on the same account for lookup."
    ]
  }
}

