messages.content:
{
  "message": "Thanks for checking that—good signal, 5G, data ON, and Airplane Mode OFF rules out several basics. Next, let’s run a few targeted checks that most often fix MMS.",
  "why_these_steps": [
    "MMS needs: active line, working mobile data, correct APN/MMSC, suitable network mode, and app permissions.",
    "We’ll rule out Wi‑Fi Calling/VPN/Data Saver interference and verify the MMSC (APN) settings."
  ],
  "request_for_identification": {
    "note": "To also check your line status, data usage, and roaming on our side, please provide one:",
    "provide_any_one_of": [
      "Phone number of the affected line (preferred)",
      "Customer ID",
      "Full name AND date of birth (YYYY-MM-DD)"
    ]
  },
  "questions_to_answer": [
    "Do text-only SMS send/receive successfully?",
    "Can you make and receive calls?",
    "With Wi‑Fi turned OFF, can you browse a website using mobile data only?",
    "Are you currently traveling outside your usual/home network area (roaming)?",
    "Do you see any specific error message when MMS fails? If yes, what does it say?",
    "Does MMS fail with all contacts or only some?"
  ],
  "on_device_steps_now": [
    {
      "step": "Turn Wi‑Fi Calling OFF and keep Wi‑Fi OFF while testing MMS.",
      "how": "check_wifi_calling_status, then toggle_wifi_calling (OFF).",
      "why": "In some cases, Wi‑Fi Calling can interfere with MMS routing."
    },
    {
      "step": "Run the MMS capability check.",
      "how": "can_send_mms and share the result.",
      "why": "Confirms whether the phone/app meets MMS prerequisites."
    },
    {
      "step": "Verify APN/MMSC settings; reset if missing/incorrect.",
      "how": "check_apn_settings. If MMSC URL is missing or looks incorrect, run reset_apn_settings, then reboot_device.",
      "why": "An incorrect or missing MMSC is a very common MMS failure cause. A reboot applies the reset."
    },
    {
      "step": "Ensure Data Saver is OFF.",
      "how": "check_data_restriction_status; if ON, toggle_data_saver_mode to OFF.",
      "why": "Data Saver can block background data needed by MMS."
    },
    {
      "step": "If a VPN is active, disconnect it.",
      "how": "check_vpn_status; if connected, disconnect_vpn.",
      "why": "Some VPNs break or slow MMS connections."
    },
    {
      "step": "Confirm preferred network mode is modern.",
      "how": "check_network_mode_preference; if set to 2G/3G, set_network_mode_preference to \"4g_5g_preferred\".",
      "why": "Older modes can prevent MMS. You’re seeing 5G, but let’s ensure the preference is correct."
    },
    {
      "step": "Confirm messaging app permissions.",
      "how": "check_app_permissions(app_name=\"messaging\"); if storage or sms is missing, grant_app_permission for each.",
      "why": "MMS needs storage (for media) and SMS permissions."
    },
    {
      "step": "If you are abroad, enable Data Roaming on the phone.",
      "how": "check_network_status; if outside home network, toggle_roaming to ON.",
      "why": "MMS requires mobile data; roaming must be allowed when outside the home network. I’ll also verify/enable roaming on your line once you share your number."
    }
  ],
  "what_to_report_back": [
    "Your phone number (or other ID) so I can check your line, data usage, and roaming status.",
    "Results of can_send_mms.",
    "Whether MMSC was present, and if you reset APN + rebooted.",
    "Whether Wi‑Fi Calling/Data Saver/VPN were ON and what changed after turning them OFF.",
    "Whether MMS now sends successfully after these steps."
  ],
  "next": "As soon as you share your phone number (or other ID) and the results above, I’ll check your account/line on our side and continue with the fastest fix."
}

