{
  "message": "Thanks for checking. Since your MMSC URL is present, let’s avoid resetting APN for now and try a few faster checks that commonly fix MMS. If it still fails after these, we’ll reset APN and reboot.",
  "why_these_steps": [
    "A present MMSC usually means APN is not the root cause. Data Saver, VPN, permissions, or mode preferences often block MMS.",
    "Resetting APN + reboot is safe but disruptive; we’ll keep it as the next step if needed."
  ],
  "actions_now_on_your_phone": [
    {
      "step": "Run the MMS capability check",
      "how": "Use can_send_mms and share the exact result.",
      "why": "Confirms whether the phone/app meets MMS prerequisites."
    },
    {
      "step": "Verify Data Saver is OFF",
      "how": "Use check_data_restriction_status; if ON, use toggle_data_saver_mode to turn it OFF.",
      "why": "Data Saver can block background data needed by MMS."
    },
    {
      "step": "Check VPN",
      "how": "Use check_vpn_status; if connected, use disconnect_vpn.",
      "why": "Some VPNs interfere with MMS routing."
    },
    {
      "step": "Confirm preferred network mode",
      "how": "Use check_network_mode_preference; if set to 2G/3G, set_network_mode_preference to \"4g_5g_preferred\".",
      "why": "Ensures a modern network stack for MMS."
    },
    {
      "step": "Confirm messaging app permissions",
      "how": "Use check_app_permissions(app_name=\"messaging\"); if storage or sms is missing, grant_app_permission for each.",
      "why": "MMS needs storage (for media) and SMS permission."
    },
    {
      "step": "Quick refresh of mobile data",
      "how": "Use toggle_data to turn mobile data OFF, wait 5 seconds, then ON.",
      "why": "Resets the data session that MMS uses."
    },
    {
      "step": "Test MMS",
      "how": "Keep Wi‑Fi OFF. Send a small photo to yourself or a known working contact. Note any error and time.",
      "why": "Verifies if the changes resolved it."
    }
  ],
  "if_still_failing_after_above": [
    {
      "step": "Reset APN and reboot",
      "how": "Use reset_apn_settings, then reboot_device.",
      "why": "Applies clean default APN/MMSC settings in case of subtle misconfiguration."
    }
  ],
  "request_for_identification": {
    "note": "I can also check your line status, data usage, and roaming on our side.",
