  "step_by_step": [
    {
      "title": "Confirm mobile data is actually working",
      "instructions": [
        "Keep Wi‑Fi OFF and Mobile data ON.",
        "Open a browser and load any site (e.g., example.com).",
        "If it doesn’t load, tell me what error you see."
