    {
      "title": "Turn Wi‑Fi Calling OFF (temporarily)",
      "instructions": [
        "Settings > Network & Internet (or Connections) > Mobile network.",
        "Tap Wi‑Fi Calling and turn it OFF.",
        "Reason: Some configurations don’t handle MMS over Wi‑Fi Calling, especially while roaming."
      ]
    },
    {
      "title": "Reset APN to defaults (refreshes MMSC for MMS)",
      "instructions": [
        "Settings > Network & Internet (or Connections) > Mobile network > Access Point Names.",
        "Tap the three‑dot menu (⋮) and choose Reset to default (or Reset APNs).",
        "Do not edit individual fields; use the reset option."
      ]
    },
    {
      "title": "Reboot the phone",
      "instructions": [
        "Restart your phone so the new APN/MMSC settings fully apply.",
        "After reboot: ensure Mobile data ON, Data roaming ON, Wi‑Fi OFF, Wi‑Fi Calling OFF."
      ]
    },
    {
      "title": "Check Data Saver",
      "instructions": [
        "Settings > Network & Internet > Data Saver.",
        "If Data Saver is ON, either turn it OFF or tap Unrestricted data and allow it for your messaging app.",
        "Reason: Data Saver can interfere with MMS background transfers."
      ]
    },
    {
      "title": "Verify messaging app permissions",
      "instructions": [
        "Settings > Apps > Your messaging app (e.g., Messages).",
