messages.content:
{
  "acknowledgement": "Good catch — those statuses will definitely prevent MMS from sending.",
  "thought_process": "MMS needs an active cellular connection with mobile data and (since you’re abroad) data roaming ON. Airplane Mode disables all radios, a missing SIM prevents the phone from registering on the network, and mobile data/roaming OFF blocks MMS.",
  "do_this_in_order": [
    {
      "step": "Turn OFF Airplane Mode",
      "how": "Android: Pull down Quick Settings and tap the airplane icon to turn it off, or go to Settings > Network & Internet (or Connections) > Airplane mode and turn it OFF.",
      "why": "Re-enables cellular radios so the phone can connect to the network."
    },
    {
      "step": "Check SIM status and reseat if needed",
      "how": "If it still says SIM missing: power the phone OFF. Eject the SIM tray, remove the SIM, gently wipe contacts, reinsert carefully in the correct orientation, and power ON.",
      "why": "Ensures the phone detects the SIM so it can register on the network."
    },
    {
      "step": "Turn ON Mobile Data",
      "how": "Settings > Network & Internet > Mobile network (or SIMs) > Mobile data ON.",
      "why": "MMS uses mobile data to send/receive media."
    },
    {
      "step": "Turn ON Data Roaming (since you’re in France)",
      "how": "Settings > Network & Internet > Mobile network > Roaming ON.",
      "why": "Allows data over partner networks while abroad. Your line’s roaming is enabled on our side."
    },
    {
      "step": "Set Preferred Network to 4G/5G",
      "how": "Settings > Network & Internet > Mobile network > Preferred network type > 4G/5G.",
      "why": "Ensures adequate speed and compatibility for MMS."
    },
    {
      "step": "Keep Wi‑Fi OFF for the test",
      "how": "Turn Wi‑Fi OFF temporarily in Quick Settings.",
      "why": "For some setups, MMS won’t send over Wi‑Fi; this forces mobile data usage for the test."
    },
    {
      "step": "Send a small photo MMS",
      "how": "Send to yourself first, then to one known contact. Wait up to 1–2 minutes.",
      "why": "Confirms end‑to‑end MMS functionality."
    }
  ],
  "after_success": [
    "You can turn Wi‑Fi back ON for other apps.",
    "Optionally re-enable Wi‑Fi Calling if you use it.",
    "Keep Data Roaming ON while you’re in France."
  ],
  "if_issue_persists": [
    "Still shows SIM missing after reseat: try the SIM in another phone (if available) or try another known‑good SIM in your phone. If the SIM remains undetected, it may be a SIM or SIM‑tray/reader issue and we can arrange help.",
    "If SIM is detected but MMS still hangs: reset APN to default (Settings > Mobile network > Access Point Names > Reset to default), then reboot and try again.",
    "Confirm Data Saver is OFF and no VPN is active."
  ],
  "ask_for_update": "Please follow the steps above and tell me what you see after each key step: does the SIM show as detected, do you see signal bars/4G/5G, and does the test MMS send? If the SIM remains undetected after reseating, I can transfer you to a human agent to arrange a SIM replacement or further hardware diagnostics."
}

